{
  "name": "Hinglish to Hindi Converter",
  "description": "A sophisticated tool that converts Romanized Hindi (Hinglish) into beautiful Devanagari script. It provides multiple variations, context clues, and an easy one-click copy feature."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface HindiResult {
  hindi: string;
  context: string;
}

export interface HistoryItem {
  id: string;
  input: string;
  results: HindiResult[];
  timestamp: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { HindiResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const transliterateHinglish = async (input: string): Promise<HindiResult[]> => {
  if (!input.trim()) return [];

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: `Convert this Romanized Hindi (Hinglish) into Devanagari Hindi: "${input}"`,
    config: {
      systemInstruction: "You are a specialized Hinglish-to-Hindi transliterator. Given Romanized Hindi text, return an array of possible Devanagari translations. Include formal variations, common spellings, and informal versions if applicable. Keep the context brief.",
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            hindi: {
              type: Type.STRING,
              description: "The Devanagari Hindi word or phrase."
            },
            context: {
              type: Type.STRING,
              description: "Brief context about this specific variation (e.g., 'Formal', 'Informal', 'Common Spelling')."
            }
          },
          required: ["hindi", "context"]
        }
      }
    }
  });

  try {
    const results = JSON.parse(response.text || "[]");
    return results;
  } catch (error) {
    console.error("Failed to parse Gemini response:", error);
    return [];
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { transliterateHinglish } from './services/geminiService';
import { HindiResult, HistoryItem } from './types';
import Header from './components/Header';
import InputArea from './components/InputArea';
import ResultDisplay from './components/ResultDisplay';
import HistoryPanel from './components/HistoryPanel';
import Toast from './components/Toast';

const App: React.FC = () => {
  const [input, setInput] = useState('');
  const [results, setResults] = useState<HindiResult[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [toastMessage, setToastMessage] = useState<string | null>(null);

  // Load history on mount
  useEffect(() => {
    const savedHistory = localStorage.getItem('hinglish_history');
    if (savedHistory) {
      try {
        setHistory(JSON.parse(savedHistory));
      } catch (e) {
        console.error("Error loading history", e);
      }
    }
  }, []);

  // Save history when it changes
  useEffect(() => {
    localStorage.setItem('hinglish_history', JSON.stringify(history.slice(0, 10)));
  }, [history]);

  const handleTransliterate = async () => {
    if (!input.trim()) return;

    setIsLoading(true);
    try {
      const data = await transliterateHinglish(input);
      setResults(data);

      if (data.length > 0) {
        const newItem: HistoryItem = {
          id: Date.now().toString(),
          input,
          results: data,
          timestamp: Date.now()
        };
        setHistory(prev => [newItem, ...prev].slice(0, 10));
      }
    } catch (error) {
      showToast("Conversion failed. Please try again.");
    } finally {
      setIsLoading(false);
    }
  };

  const showToast = (message: string) => {
    setToastMessage(message);
    setTimeout(() => setToastMessage(null), 3000);
  };

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    showToast("Copied to clipboard!");
  };

  const handleSelectHistory = (item: HistoryItem) => {
    setInput(item.input);
    setResults(item.results);
  };

  return (
    <div className="min-h-screen pb-20">
      <Header />

      <main className="max-w-4xl mx-auto px-4 mt-8 space-y-8">
        <section className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6 md:p-8">
          <InputArea 
            value={input}
            onChange={setInput}
            onSubmit={handleTransliterate}
            isLoading={isLoading}
          />
        </section>

        <section className="grid grid-cols-1 md:grid-cols-3 gap-8">
          <div className="md:col-span-2 space-y-4">
            <h2 className="text-xl font-semibold text-slate-800 px-2 flex items-center">
              Hindi Translations
              {results.length > 0 && (
                <span className="ml-3 px-2 py-0.5 bg-indigo-50 text-indigo-600 text-xs rounded-full">
                  {results.length} results
                </span>
              )}
            </h2>
            <ResultDisplay 
              results={results} 
              onCopy={handleCopy} 
              isLoading={isLoading} 
            />
          </div>

          <aside className="md:col-span-1">
            <HistoryPanel 
              history={history} 
              onSelect={handleSelectHistory} 
              onClear={() => setHistory([])}
            />
          </aside>
        </section>
      </main>

      {toastMessage && <Toast message={toastMessage} />}
    </div>
  );
};

export default App;

