import React from 'react';

interface InputAreaProps {
  value: string;
  onChange: (val: string) => void;
  onSubmit: () => void;
  isLoading: boolean;
}

const InputArea: React.FC<InputAreaProps> = ({ value, onChange, onSubmit, isLoading }) => {
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      onSubmit();
    }
  };

  return (
    <div className="w-full space-y-4">
      <div className="flex items-center justify-between mb-2">
        <label className="text-sm font-semibold text-slate-600">Enter Romanized Hindi</label>
        <span className="text-[10px] text-slate-400 font-mono">Example: "Namaste" or "Aap kaise hain?"</span>
      </div>

      <div className="relative">
        <textarea
          value={value}
          onChange={(e) => onChange(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Type Hinglish text here..."
          className="w-full h-32 p-4 text-lg border-2 border-slate-100 rounded-xl focus:border-indigo-500 focus:ring-0 transition-all resize-none bg-slate-50/50"
          disabled={isLoading}
        />

        <button
          onClick={onSubmit}
          disabled={isLoading || !value.trim()}
          className={`absolute bottom-4 right-4 px-6 py-2 rounded-lg font-bold text-sm shadow-md transition-all flex items-center space-x-2 
            ${isLoading || !value.trim() 
              ? 'bg-slate-200 text-slate-400 cursor-not-allowed' 
              : 'bg-indigo-600 text-white hover:bg-indigo-700 active:transform active:scale-95'}`}
        >
          {isLoading ? (
            <>
              <svg className="animate-spin h-4 w-4 text-white" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none" />
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
              </svg>
              <span>Converting...</span>
            </>
          ) : (
            <>
              <span>Convert to Hindi</span>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7-7 7M5 5l7 7-7 7" />
              </svg>
            </>
          )}
        </button>
      </div>
    </div>
  );
};

export default InputArea;

import React from 'react';
import { HindiResult } from '../types';

interface ResultDisplayProps {
  results: HindiResult[];
  onCopy: (text: string) => void;
  isLoading: boolean;
}

const ResultDisplay: React.FC<ResultDisplayProps> = ({ results, onCopy, isLoading }) => {
  if (isLoading) {
    return (
      <div className="space-y-4">
        {[1, 2].map(i => (
          <div key={i} className="bg-white p-6 rounded-2xl border border-slate-100 animate-pulse flex justify-between">
            <div className="space-y-2 w-full">
              <div className="h-8 bg-slate-100 rounded-md w-1/2"></div>
              <div className="h-4 bg-slate-50 rounded-md w-1/4"></div>
            </div>
          </div>
        ))}
      </div>
    );
  }

  if (results.length === 0) {
    return (
      <div className="bg-white border-2 border-dashed border-slate-100 rounded-2xl p-12 text-center">
        <div className="mx-auto w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mb-4">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-slate-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 10h10a8 8 0 018 8v2M3 10l6 6m-6-6l6-6" />
          </svg>
        </div>
        <p className="text-slate-400 font-medium">Results will appear here...</p>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 gap-4">
      {results.map((item, idx) => (
        <div 
          key={idx} 
          className="group bg-white border border-slate-200 rounded-2xl p-6 transition-all hover:shadow-md hover:border-indigo-200 flex flex-col md:flex-row md:items-center justify-between gap-4"
        >
          <div className="space-y-1">
            <span className="text-[10px] font-bold text-indigo-500 uppercase tracking-wider bg-indigo-50 px-2 py-0.5 rounded-md">
              {item.context}
            </span>
            <div className="hindi-font text-4xl font-bold text-slate-900 leading-tight">
              {item.hindi}
            </div>
          </div>

          <button
            onClick={() => onCopy(item.hindi)}
            className="flex items-center justify-center space-x-2 px-5 py-3 rounded-xl bg-slate-50 text-slate-600 font-semibold text-sm border border-slate-100 hover:bg-indigo-600 hover:text-white hover:border-indigo-600 transition-all"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3" />
            </svg>
            <span>Copy Text</span>
          </button>
        </div>
      ))}
    </div>
  );
};

export default ResultDisplay;

import React from 'react';
import { HistoryItem } from '../types';

interface HistoryPanelProps {
  history: HistoryItem[];
  onSelect: (item: HistoryItem) => void;
  onClear: () => void;
}

const HistoryPanel: React.FC<HistoryPanelProps> = ({ history, onSelect, onClear }) => {
  return (
    <div className="bg-white border border-slate-100 rounded-2xl overflow-hidden shadow-sm">
      <div className="p-4 border-b border-slate-50 flex items-center justify-between">
        <h3 className="font-bold text-slate-700 text-sm">Recent</h3>
        {history.length > 0 && (
          <button 
            onClick={onClear}
            className="text-[10px] font-bold text-red-500 uppercase hover:underline"
          >
            Clear
          </button>
        )}
      </div>

      <div className="max-h-[400px] overflow-y-auto">
        {history.length === 0 ? (
          <div className="p-8 text-center text-slate-300 text-sm font-medium">
            No history yet
          </div>
        ) : (
          <div className="divide-y divide-slate-50">
            {history.map((item) => (
              <button
                key={item.id}
                onClick={() => onSelect(item)}
                className="w-full p-4 text-left hover:bg-slate-50 transition-colors group"
              >
                <div className="text-sm font-semibold text-slate-800 line-clamp-1 group-hover:text-indigo-600">
                  {item.input}
                </div>
                <div className="flex items-center space-x-2 mt-1">
                  <span className="hindi-font text-xs text-slate-400">
                    {item.results[0]?.hindi}
                  </span>
                  <span className="text-[10px] text-slate-300">
                    • {new Date(item.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default HistoryPanel;

